// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address newOwner) public {
        // The test contract is the deployer, hence the current owner of c.
        // Restrict domain: the new owner must not coincide with c's own address
        // (that single input is where P and M legitimately agree).
        vm.assume(newOwner != address(c));

        vm.prank(address(this));
        bool ok;
        try c.setOwner(newOwner) returns (bool s) { ok = s; } catch { ok = false; }

        assertTrue(ok && c.owner() == newOwner);
    }
}
